<script setup lang="ts">
import { Users, Circle, Star, UserPlus, Inbox, Search, Settings2, Folder, Plus, MessageSquare, ArrowUpRight, RefreshCw, Pencil, Trash2, X, MoreHorizontal, ArrowLeft } from '@lucide/vue'
import type { ForumUser } from '~~/shared/forum'
import type { SocialUser } from '~~/shared/social'
import { apiErrorMessage } from '~/utils/apiError'
import { formatRelativeTime } from '~/utils/forum'
definePageMeta({ middleware: 'auth', keepalive: true })
useSeoMeta({ title: '好友中心 – DevBit Tech', robots: 'noindex, nofollow' })
const route = useRoute(), router = useRouter()
const auth = useAuth()
const { state, api, refresh, loadFriends, loadRequests, loadSettings, run } = useSocialWorkspace()
const { status: connection } = useWebSocket()
const view = computed(() => typeof route.query.view === 'string' ? route.query.view : state.value.friendsView)
const direction = ref<'incoming' | 'outgoing'>('incoming'), query = ref(state.value.friendQuery.q ?? ''), composing = ref(false)
const results = ref<SocialUser[]>([]), searchStatus = ref<'idle' | 'loading' | 'success' | 'error'>('idle'), searchError = ref(''), searchCursor = ref<string | null>(null)
const selected = ref<{ id: number; user?: ForumUser } | null>(null), list = ref<HTMLElement>(), groupEditor = ref<{ id?: number; name: string } | null>(null), groupDelete = ref<number | null>(null), groupInput = ref<HTMLInputElement>()
let timer: ReturnType<typeof setTimeout> | undefined, searchSerial = 0, active = true, previousGroupFocus: HTMLElement | null = null
const nav = computed(() => [
  { id: 'all', label: api.value.mode === 'legacy' ? '全部联系人' : '全部好友', icon: Users, count: state.value.summary?.total },
  { id: 'online', label: '当前在线', icon: Circle, count: state.value.summary?.online },
  { id: 'starred', label: '星标好友', icon: Star, count: state.value.summary?.starred },
  { id: 'requests', label: '好友申请', icon: Inbox, count: state.value.summary?.incoming ?? state.value.incoming.length },
  { id: 'discover', label: '寻找成员', icon: UserPlus },
])
const title = computed(() => nav.value.find(n => n.id === view.value)?.label ?? (view.value === 'settings' ? '隐私与屏蔽' : view.value === 'ungrouped' ? '未分组' : state.value.groups.find(g => `group:${g.id}` === view.value)?.name ?? '好友中心'))
const isList = computed(() => !['requests', 'discover', 'settings'].includes(view.value))
const unsupported = computed(() => view.value === 'online' && !api.value.capabilities.presence || (view.value === 'starred' && !api.value.capabilities.metadata) || ((view.value.startsWith('group:') || view.value === 'ungrouped') && !api.value.capabilities.groups))
const rows = computed(() => {
  const q = query.value.trim().toLocaleLowerCase()
  return state.value.friends.filter(f => (api.value.capabilities.directory || !q || `${f.user.name}${f.metadata?.note ?? ''}`.toLocaleLowerCase().includes(q)) && (view.value !== 'online' || state.value.presence[f.user.id] === 'online') && (view.value !== 'starred' || f.metadata?.starred))
})
const displayResults = computed(() => results.value.map(member => ({ ...member, ...state.value.members[member.id] })))
const requestRows = computed(() => state.value[direction.value])
function choose(id: string) { state.value.friendsView = id; state.value.scroll = 0; query.value = ''; selected.value = null; void router.replace({ query: { view: id } }) }
function syncQuery() {
  state.value.friendsView = view.value
  state.value.friendQuery = { q: isList.value ? query.value.trim() || undefined : undefined, status: view.value === 'online' ? 'online' : undefined, starred: view.value === 'starred' ? true : undefined, groupId: view.value === 'ungrouped' ? null : view.value.startsWith('group:') ? Number(view.value.split(':')[1]) : undefined }
  if (isList.value && !unsupported.value) void loadFriends()
  if (view.value === 'settings') void loadSettings()
}
watch(view, () => { searchSerial++; searchStatus.value = 'idle'; results.value = []; syncQuery() })
watch(query, () => { searchSerial++; clearTimeout(timer); if (view.value === 'discover') { searchStatus.value = 'idle'; results.value = []; searchCursor.value = null }; if (!composing.value) timer = setTimeout(() => view.value === 'discover' ? void search() : syncQuery(), 300) })
function startComposition() { composing.value = true; searchSerial++; clearTimeout(timer) }
function endComposition() { composing.value = false; clearTimeout(timer); timer = setTimeout(() => view.value === 'discover' ? void search() : syncQuery(), 300) }
async function search(append = false) {
  clearTimeout(timer); if (composing.value) return
  const q = query.value.trim(), serial = ++searchSerial, owner = auth.user.value?.id
  if (!q) { searchStatus.value = 'idle'; results.value = []; return }
  searchStatus.value = 'loading'; searchError.value = ''; const service = api.value
  try { const page = await service.searchUsers(q, append ? searchCursor.value ?? undefined : undefined); if (!active || serial !== searchSerial || owner !== auth.user.value?.id) return; results.value = append ? [...new Map([...results.value, ...page.items].map(u => [u.id, u])).values()] : page.items; searchCursor.value = page.nextCursor; searchStatus.value = 'success' }
  catch (e) { if (active && serial === searchSerial && owner === auth.user.value?.id) { searchStatus.value = 'error'; searchError.value = apiErrorMessage(e) } }
}
function openProfile(user: ForumUser) { selected.value = { id: user.id, user } }
async function decide(id: number, action: 'accept' | 'reject' | 'cancel') { await run(`request:${id}`, s => action === 'accept' ? s.acceptRequest(id) : action === 'reject' ? s.rejectRequest(id) : s.cancelRequest(id), action === 'accept' ? '已成为好友，开始交流吧' : action === 'reject' ? '已忽略申请' : '已撤回申请') }
function editGroup(id?: number, name = '') { state.value.errors['group-edit'] = ''; previousGroupFocus = document.activeElement as HTMLElement; groupEditor.value = { id, name }; nextTick(() => groupInput.value?.focus()) }
function closeGroup() { groupEditor.value = null; previousGroupFocus?.focus() }
async function saveGroup() { const editor = groupEditor.value; if (!editor?.name.trim()) return; if (await run('group-edit', s => editor.id ? s.renameGroup(editor.id, editor.name.trim()) : s.createGroup(editor.name.trim()), '分组已保存')) closeGroup() }
async function deleteGroup() { const id = groupDelete.value; if (!id) return; if (await run('group-delete', s => s.deleteGroup(id), '分组已删除，好友已移至未分组')) { groupDelete.value = null; choose('all') } }
function trapGroup(e: KeyboardEvent) { if (e.key === 'Escape') { e.stopPropagation(); closeGroup() }; if (e.key !== 'Tab') return; const controls = [...(e.currentTarget as HTMLElement).querySelectorAll<HTMLElement>('input, button:not(:disabled)')]; if (e.shiftKey && document.activeElement === controls[0]) { e.preventDefault(); controls.at(-1)?.focus() } else if (!e.shiftKey && document.activeElement === controls.at(-1)) { e.preventDefault(); controls[0]?.focus() } }
function presence(id: number) { return state.value.presence[id] === 'online' ? '在线' : state.value.presence[id] === 'offline' ? '离线' : '状态未确认' }
onMounted(async () => { syncQuery(); await refresh(); await nextTick(); if (list.value) list.value.scrollTop = state.value.scroll })
onActivated(() => { active = true; if (list.value) list.value.scrollTop = state.value.scroll })
onDeactivated(() => { active = false; searchSerial++; clearTimeout(timer); selected.value = null })
onBeforeUnmount(() => { active = false; searchSerial++; clearTimeout(timer) })
</script>
<template>
  <div class="soc-page soc-friends-page">
    <h1 class="sr-only">好友中心</h1>
    <p v-if="api.mode === 'legacy'" class="soc-connection">当前为单向联系人模式，添加无需对方确认；双向好友申请尚未开放。</p>
    <p v-if="api.mode !== 'mock' && api.capabilities.presence && connection !== 'connected'" class="soc-connection" role="status">实时连接暂未就绪，在线状态可能暂时不可用。</p>
    <div class="soc-shell" :class="{ 'soc-shell--profile': selected }">
      <aside class="soc-sidebar"><div class="soc-sidebar__label">我的连接</div><nav aria-label="好友分类"><button v-for="item in nav" :key="item.id" class="soc-nav" :class="{ 'is-active': view === item.id }" :aria-current="view === item.id ? 'page' : undefined" @click="choose(item.id)"><component :is="item.icon" :size="18" /><span>{{ item.label }}</span><small v-if="item.count !== undefined" :class="{ 'soc-badge': item.id === 'requests' && item.count }">{{ item.count }}</small></button></nav><div class="soc-sidebar__label soc-sidebar__groups">好友分组<button v-if="api.capabilities.groups" class="soc-icon" aria-label="新建好友分组" @click="editGroup()"><Plus :size="16" /></button></div><div v-if="api.capabilities.groups"><button class="soc-nav" :class="{ 'is-active': view === 'ungrouped' }" @click="choose('ungrouped')"><Folder :size="17" /><span>未分组</span></button><button v-for="group in state.groups" :key="group.id" class="soc-nav" :class="{ 'is-active': view === `group:${group.id}` }" @click="choose(`group:${group.id}`)"><Folder :size="17" /><span>{{ group.name }}</span></button><p v-if="state.errors.groups" class="soc-error" role="alert">{{ state.errors.groups }}</p></div><p v-else class="soc-sidebar__hint">分组功能暂未开放</p><div class="soc-sidebar__bottom"><button class="soc-nav" :class="{ 'is-active': view === 'settings' }" @click="choose('settings')"><Settings2 :size="18" /><span>隐私与屏蔽</span></button><NuxtLink class="soc-nav soc-nav--muted" to="/forum"><ArrowLeft :size="17" /><span>回到社区</span></NuxtLink></div></aside>
      <section class="soc-main" :aria-label="title">
        <header class="soc-content-heading"><div><h2>{{ title }} <span v-if="isList && state.friendsTotal !== null" class="soc-count">{{ state.friendsTotal }}</span></h2><p>{{ view === 'discover' ? '从一次交流，开始一段新的连接。' : view === 'requests' ? '每一个招呼，都可能带来新的灵感。' : view === 'settings' ? '按照自己的节奏，选择与谁交流。' : '熟悉的名字，新的灵感。' }}</p></div><div class="soc-heading-actions"><template v-if="view.startsWith('group:')"><button class="soc-icon" aria-label="重命名分组" @click="editGroup(Number(view.split(':')[1]), title)"><Pencil :size="17" /></button><button class="soc-icon soc-danger" aria-label="删除分组" @click="groupDelete = Number(view.split(':')[1])"><Trash2 :size="17" /></button></template><button class="soc-icon" aria-label="刷新好友中心" :disabled="state.busy.friends" @click="refresh()"><RefreshCw :size="17" /></button><button v-if="view !== 'discover'" class="soc-btn soc-btn--primary" @click="choose('discover')"><UserPlus :size="17" /><span>添加好友</span></button></div></header>
        <div v-if="state.notice" class="soc-success" role="status">{{ state.notice }}<button class="soc-icon" aria-label="关闭提示" @click="state.notice = ''"><X :size="16" /></button></div>
        <form v-if="isList || view === 'discover'" class="soc-search" role="search" @submit.prevent="view === 'discover' ? search() : syncQuery()"><Search :size="18" aria-hidden="true" /><label class="sr-only" for="social-search">{{ view === 'discover' ? '搜索社区成员' : '搜索好友昵称或备注' }}</label><input id="social-search" v-model="query" :placeholder="view === 'discover' ? '搜索社区成员昵称…' : api.capabilities.directory || api.mode === 'legacy' ? '搜索昵称或备注…' : '搜索已加载的好友…'" autocomplete="off" @compositionstart="startComposition" @compositionend="endComposition"><button v-if="query" type="button" class="soc-icon" aria-label="清空搜索" @click="query = ''"><X :size="16" /></button><button v-if="view === 'discover'" class="soc-btn soc-btn--small" :disabled="composing || !query.trim() || searchStatus === 'loading'">搜索</button><kbd v-else aria-hidden="true">搜索</kbd></form>
        <div ref="list" class="soc-list-scroll" @scroll="state.scroll = ($event.target as HTMLElement).scrollTop">
          <template v-if="isList">
            <SocialEmptyState v-if="unsupported" title="此功能暂未开放" description="后端接入后即可在这里管理好友。" />
            <template v-else><p v-if="view === 'online' && state.errors.presence" class="soc-error" role="alert">{{ state.errors.presence }}</p><div v-if="state.errors.friends" class="soc-error" role="alert">{{ state.errors.friends }}<button @click="loadFriends()">重新加载</button></div><div v-if="state.busy.friends && !state.friends.length" class="soc-skeletons" role="status" aria-label="正在加载好友"><div v-for="i in 5" :key="i" class="soc-skeleton"></div></div><SocialEmptyState v-else-if="!rows.length && !state.errors.friends" :title="query ? '没有找到匹配的好友' : view === 'online' ? '好友们暂时不在线' : view === 'starred' ? '把重要的人放在这里' : '这里还没有好友'" :description="query ? '换个昵称或备注试试。' : view === 'starred' ? '在好友资料里添加星标，下次更快找到。' : '去社区打个招呼，或者搜索你认识的成员。'"><button v-if="view === 'all'" class="soc-btn soc-btn--primary" @click="choose('discover')">寻找社区成员</button></SocialEmptyState>
              <div v-if="rows.length" class="soc-list-caption"><span>{{ query ? '搜索结果' : '成员' }}</span><span>保持联系</span></div>
              <article v-for="friend in rows" :key="friend.user.id" class="soc-person" :class="{ 'is-selected': selected?.id === friend.user.id }"><button class="soc-avatar-button" :aria-label="`查看 ${friend.user.name} 的资料`" :data-tone="friend.user.id % 5" @click="openProfile(friend.user)"><AvatarImage :name="friend.user.name" :avatar="friend.user.avatar" :avatar-url="friend.user.avatarUrl" /><span v-if="api.capabilities.presence" class="soc-presence-dot" :class="{ 'is-online': state.presence[friend.user.id] === 'online' }"></span></button><button class="soc-person__identity" @click="openProfile(friend.user)"><strong>{{ friend.metadata?.note || friend.user.name }}<Star v-if="friend.metadata?.starred" :size="13" class="soc-star" fill="currentColor" /></strong><span>{{ friend.metadata?.note ? friend.user.name + ' · ' : '' }}{{ api.capabilities.presence ? presence(friend.user.id) : api.mode === 'legacy' ? '单向联系人' : '社区好友' }}</span></button><span v-if="state.conversations.find(c => c.user.id === friend.user.id)?.unread" class="soc-badge">{{ state.conversations.find(c => c.user.id === friend.user.id)?.unread }}</span><NuxtLink v-if="friend.user.canMessage" class="soc-message-action" :to="`/messages/${friend.user.id}`" :aria-label="`给 ${friend.user.name} 发消息`"><MessageSquare :size="18" /><span>发消息</span></NuxtLink><button v-else class="soc-icon" disabled aria-label="当前无法发送私信"><MessageSquare :size="18" /></button><button class="soc-icon" :aria-label="`管理 ${friend.user.name}`" @click="openProfile(friend.user)"><MoreHorizontal :size="19" /></button></article>
              <button v-if="state.friendsCursor" class="soc-btn soc-load-more" :disabled="state.busy.friends" @click="loadFriends(true)">加载更多好友</button><p v-else-if="rows.length" class="soc-list-end">每一次交流，都是新的开始</p></template>
          </template>
          <template v-else-if="view === 'requests'"><SocialEmptyState v-if="!api.capabilities.requests" title="好友申请暂未开放" description="当前使用单向联系人，添加无需对方确认。" /><template v-else><div class="soc-segments" aria-label="申请方向"><button :aria-pressed="direction === 'incoming'" @click="direction = 'incoming'">收到的申请<span>{{ state.summary?.incoming ?? state.incoming.length }}{{ !state.summary && state.requestCursors.incoming ? '+' : '' }}</span></button><button :aria-pressed="direction === 'outgoing'" @click="direction = 'outgoing'">发出的申请</button></div><p v-if="state.busy[direction] && !requestRows.length" class="soc-loading" role="status">正在加载申请…</p><div v-if="state.errors[direction]" class="soc-error" role="alert">{{ state.errors[direction] }}<button @click="loadRequests(direction)">重试</button></div><SocialEmptyState v-if="!requestRows.length && !state.busy[direction] && !state.errors[direction]" title="暂时没有待处理申请" description="新的好友申请会出现在这里。" /><article v-for="request in requestRows" :key="request.id" class="soc-request"><div class="soc-person"><button class="soc-avatar-button" :data-tone="request.id % 5" :aria-label="`查看 ${direction === 'incoming' ? request.sender.name : request.recipient.name} 的资料`" @click="openProfile(direction === 'incoming' ? request.sender : request.recipient)"><AvatarImage v-bind="direction === 'incoming' ? { name: request.sender.name, avatar: request.sender.avatar, avatarUrl: request.sender.avatarUrl } : { name: request.recipient.name, avatar: request.recipient.avatar, avatarUrl: request.recipient.avatarUrl }" /></button><button class="soc-person__identity" @click="openProfile(direction === 'incoming' ? request.sender : request.recipient)"><strong>{{ direction === 'incoming' ? request.sender.name : request.recipient.name }}</strong><span>{{ formatRelativeTime(request.createdAt) }} · #{{ direction === 'incoming' ? request.sender.id : request.recipient.id }}</span></button><div class="soc-request__actions"><template v-if="direction === 'incoming'"><button class="soc-btn soc-btn--primary" :disabled="state.busy[`request:${request.id}`]" @click="decide(request.id, 'accept')">接受</button><button class="soc-btn" :disabled="state.busy[`request:${request.id}`]" @click="decide(request.id, 'reject')">忽略</button></template><button v-else class="soc-btn" :disabled="state.busy[`request:${request.id}`]" @click="decide(request.id, 'cancel')">撤回申请</button></div></div><p class="soc-request__message">{{ request.message || '想和你一起交流学习与创作。' }}</p><p v-if="state.errors[`request:${request.id}`]" class="soc-error" role="alert">{{ state.errors[`request:${request.id}`] }}</p></article><button v-if="state.requestCursors[direction]" class="soc-btn soc-load-more" :disabled="state.busy[direction]" @click="loadRequests(direction, true)">加载更多申请</button></template></template>
          <template v-else-if="view === 'discover'"><SocialEmptyState v-if="searchStatus === 'idle'" title="你的下一位同路人，就在这里" description="输入昵称寻找社区成员，先看看资料，再带上一句真诚的招呼。"><NuxtLink to="/forum" class="soc-btn">去社区逛逛<ArrowUpRight :size="16" /></NuxtLink></SocialEmptyState><p v-if="searchStatus === 'loading'" class="soc-loading" role="status">正在寻找成员…</p><div v-if="searchStatus === 'error'" class="soc-error" role="alert">{{ searchError }}<button @click="search()">重试</button></div><SocialEmptyState v-if="searchStatus === 'success' && !results.length" title="没有找到这位成员" description="请检查昵称，或试试其中几个字。" /><article v-for="member in displayResults" :key="member.id" class="soc-person"><button class="soc-avatar-button" :data-tone="member.id % 5" :aria-label="`查看 ${member.name} 的资料`" @click="openProfile(member)"><AvatarImage :name="member.name" :avatar="member.avatar" :avatar-url="member.avatarUrl" /></button><button class="soc-person__identity" @click="openProfile(member)"><strong>{{ member.name }}</strong><span>社区成员 #{{ member.id }} · {{ member.relationship === 'friends' ? '已是好友' : member.relationship === 'outgoing_pending' ? '等待确认' : member.relationship === 'incoming_pending' ? '已向你申请' : member.relationship === 'self' ? '你自己' : member.relationship === 'blocked' ? '已屏蔽' : member.relationship === 'contact' ? '单向联系人' : '尚未建立连接' }}</span></button><button class="soc-btn" @click="openProfile(member)">查看资料<ArrowUpRight :size="15" /></button></article><button v-if="searchCursor" class="soc-btn soc-load-more" :disabled="searchStatus === 'loading'" @click="search(true)">加载更多成员</button></template>
          <template v-else-if="view === 'settings'"><form v-if="api.capabilities.preferences" class="soc-settings soc-form" @submit.prevent="run('save-preferences', s => s.updatePreferences({ ...state.preferences }), '隐私偏好已保存')"><h3>交流偏好</h3><p>为自己留出舒适的交流空间。</p><label for="message-policy">谁可以给我发私信</label><select id="message-policy" v-model="state.preferences.messagePolicy" class="soc-input" :disabled="!state.settingsLoaded"><option value="everyone">所有社区成员</option><option value="friends">仅好友</option><option value="nobody">暂不接收</option></select><label for="request-policy">谁可以申请添加我</label><select id="request-policy" v-model="state.preferences.friendRequestPolicy" class="soc-input" :disabled="!state.settingsLoaded"><option value="everyone">所有社区成员</option><option value="nobody">暂不接收</option></select><button class="soc-btn soc-btn--primary" :disabled="!state.settingsLoaded || state.busy['save-preferences']">保存偏好</button><p v-if="state.errors['save-preferences']" role="alert" class="soc-error">{{ state.errors['save-preferences'] }}</p></form><p v-else class="soc-note soc-settings">交流偏好暂未开放。</p><div v-if="state.errors.preferences || state.errors.blocks" class="soc-error" role="alert">{{ state.errors.preferences || state.errors.blocks }}<button @click="loadSettings()">重试</button></div><div class="soc-settings"><h3>屏蔽列表</h3><p class="soc-note">屏蔽成员后，无法互发私信。解除屏蔽不会自动添加好友。</p><p v-if="!api.capabilities.blocks" class="soc-note">屏蔽功能暂未开放。</p><p v-else-if="!state.blocked.length && !state.busy.blocks && !state.errors.blocks" class="soc-note">目前没有屏蔽的成员。</p><article v-for="member in state.blocked" :key="member.id" class="soc-person"><button class="soc-person__identity" @click="openProfile(member)"><strong>{{ member.name }}</strong><span>#{{ member.id }}</span></button><button class="soc-btn" :disabled="state.busy[`unblock:${member.id}`]" @click="run(`unblock:${member.id}`, s => s.unblock(member.id), '已解除屏蔽').then(() => loadSettings())">解除屏蔽</button><p v-if="state.errors[`unblock:${member.id}`]" role="alert" class="soc-error">{{ state.errors[`unblock:${member.id}`] }}</p></article><button v-if="state.blocksCursor" class="soc-btn" @click="loadSettings(true)">加载更多</button></div></template>
        </div>
      </section>
      <SocialProfileDrawer v-if="selected" :key="selected.id" :user-id="selected.id" :known="selected.user" @close="selected = null" />
    </div>
    <p v-if="api.mode === 'mock'" class="soc-demo soc-friends-demo">开发演示 · 所有操作仅影响本次演示，刷新后重置</p>
    <Teleport to="body"><div v-if="groupEditor" class="confirm-overlay" @click.self="closeGroup()"><form class="confirm-dialog soc-form" role="dialog" aria-modal="true" aria-labelledby="group-editor-title" @submit.prevent="saveGroup" @keydown="trapGroup"><h2 id="group-editor-title">{{ groupEditor.id ? '重命名分组' : '新建好友分组' }}</h2><label for="group-name">分组名称</label><input id="group-name" ref="groupInput" v-model="groupEditor.name" class="soc-input" required maxlength="30" placeholder="例如：一起写代码"><p v-if="state.errors['group-edit']" class="soc-error" role="alert">{{ state.errors['group-edit'] }}</p><div class="confirm-dialog__actions"><button type="button" class="soc-btn" :disabled="state.busy['group-edit']" @click="closeGroup()">取消</button><button class="soc-btn soc-btn--primary" :disabled="!groupEditor.name.trim() || state.busy['group-edit']">保存分组</button></div></form></div></Teleport>
    <ConfirmDialog :open="!!groupDelete" title="删除好友分组" description="分组内的好友将移至未分组，好友关系和聊天记录会保留。" :busy="state.busy['group-delete']" :error="state.errors['group-delete']" confirm-label="删除分组" @cancel="groupDelete = null" @confirm="deleteGroup" />
  </div>
</template>
